PRAGMA foreign_keys = ON;

DELETE FROM applications WHERE public_id IN (
  'IND-EV-26-DEMO01', 'IND-EV-26-DEMO02', 'IND-EV-26-DEMO03',
  'IND-EV-26-DEMO04', 'IND-EV-26-DEMO05', 'IND-EV-26-DEMO06'
);



  SELECT id, json_extract(sections_json, '$.personal.surname'), json_extract(sections_json, '$.personal.givenNames'), json_extract(sections_json, '$.personal.gender'), json_extract(sections_json, '$.personal.birthCity'), json_extract(sections_json, '$.personal.birthCountry'), json_extract(sections_json, '$.personal.citizenship'), json_extract(sections_json, '$.personal.religion'), json_extract(sections_json, '$.personal.identificationMarks'), json_extract(sections_json, '$.personal.education'), COALESCE(json_extract(sections_json, '$.personal'), '{}'), updated_at FROM applications WHERE public_id LIKE 'IND-EV-26-DEMO%';
  SELECT id, json_extract(sections_json, '$.passport.passportNumber'), json_extract(sections_json, '$.passport.passportType'), json_extract(sections_json, '$.passport.issuingCountry'), json_extract(sections_json, '$.passport.placeOfIssue'), json_extract(sections_json, '$.passport.issueDate'), json_extract(sections_json, '$.passport.expiryDate'), COALESCE(json_extract(sections_json, '$.passport'), '{}'), updated_at FROM applications WHERE public_id LIKE 'IND-EV-26-DEMO%';





